const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Global land area (represented by the image collection's global coverage).
    // Using a simple global rectangle, but the reducer should handle global.
    const global_geom = ee.Geometry.Rectangle([-180, -90, 180, 90], null, false); // For maxPixels

    const year2003 = 2003;
    const year2019 = 2019;

    // 2. Data Acquisition & Check
    // MODIS Land Cover Type Yearly Global 500m (MCD12Q1)
    // Band: 'LC_Type1' (IGBP classification)
    // Class 12: Croplands
    const collection = ee.ImageCollection('MODIS/051/MCD12Q1');

    const img2003_col = collection.filterDate(`${year2003}-01-01`, `${year2003}-12-31`);
    const img2019_col = collection.filterDate(`${year2019}-01-01`, `${year2019}-12-31`);

    if (img2003_col.size().getInfo() === 0) {
      console.log(`No MODIS MCD12Q1 data found for ${year2003}.`);
      console.log('C1');
      return;
    }
    if (img2019_col.size().getInfo() === 0) {
      console.log(`No MODIS MCD12Q1 data found for ${year2019}.`);
      console.log('C1');
      return;
    }

    // Take the first image for the respective year (MCD12Q1 is yearly, so there should be one).
    const img2003 = img2003_col.first().select('LC_Type1');
    const img2019 = img2019_col.first().select('LC_Type1');

    // 3. Processing: Mask for Croplands (IGBP class 12)
    const croplandMask2003 = img2003.eq(12); // Class 12 is 'Croplands'
    const croplandMask2019 = img2019.eq(12);

    // Calculate pixel area for each image.
    const pixelArea = ee.Image.pixelArea();

    // Multiply the pixel area by the cropland mask to get cropland area in square meters.
    const croplandArea2003_img = pixelArea.updateMask(croplandMask2003);
    const croplandArea2019_img = pixelArea.updateMask(croplandMask2019);

    // 4. Calculation: Sum the cropland areas globally
    const scale = 500; // MODIS resolution is 500m
    const maxPixels = 1e10; // Allow for large global calculations

    const areaReducer = ee.Reducer.sum();

    const area2003_val = await croplandArea2003_img.reduceRegion({
      reducer: areaReducer,
      geometry: global_geom,
      scale: scale,
      maxPixels: maxPixels
    }).get('area').getInfo(); // 'area' is the default band name for pixelArea()

    const area2019_val = await croplandArea2019_img.reduceRegion({
      reducer: areaReducer,
      geometry: global_geom,
      scale: scale,
      maxPixels: maxPixels
    }).get('area').getInfo();

    // Convert to km^2 for readability in logs
    const area2003_km2 = area2003_val / 1e6;
    const area2019_km2 = area2019_val / 1e6;

    // Check for C2 (No Valid Pixels) or C3 (Calculation Failure)
    if (area2003_val === 0 || area2019_val === 0) {
      console.log(`Cropland area for 2003: ${area2003_km2.toFixed(0)} km²`);
      console.log(`Cropland area for 2019: ${area2019_km2.toFixed(0)} km²`);
      console.log('No valid cropland pixels found after processing.');
      console.log('C2');
      return;
    }

    if (area2003_val === null || area2019_val === null || isNaN(area2003_val) || isNaN(area2019_val)) {
      console.log('Error: Area calculation resulted in null or NaN.');
      console.log('C3');
      return;
    }

    // Calculate percentage increase
    const percentageIncrease = ((area2019_val - area2003_val) / area2003_val) * 100;

    // 5. Validation & Final Answer
    console.log(`Global cropland area ${year2003}: ${area2003_km2.toFixed(0)} km²`);
    console.log(`Global cropland area ${year2019}: ${area2019_km2.toFixed(0)} km²`);
    console.log(`Percentage increase: ${percentageIncrease.toFixed(2)}%`);

    if (percentageIncrease >= 5) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (e) {
    console.error("An error occurred during analysis:", e);
    // This could catch various GEE errors, including incorrect band names, memory issues, etc.
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
